class.description:
Recommends graphics settings in tiers, from [constant TIER_ULTRA] down to [constant TIER_LOW]. [method get_tier] picks a starting tier from the graphics adapter, [method get_settings] gives a tier's engine settings for the screen or a headset and [method apply] sets them on a viewport. [method benchmark] measures the tiers in the game itself and keeps the best one that holds a frame rate.
A game usually adds its own settings to each tier (draw distance, crowd density) and applies both together:
[codeblock]
func apply_tier(tier: RecommendedGraphics.Tier) -> void:
    RecommendedGraphics.apply(get_viewport(), RecommendedGraphics.get_settings(tier))
    crowd_density = [1.0, 1.0, 0.6, 0.3][tier]

func _ready() -> void:
    apply_tier(RecommendedGraphics.get_tier())

func _on_use_recommended_pressed() -> void:
    var tier: RecommendedGraphics.Tier = await RecommendedGraphics.benchmark(apply_tier, 60.0)
    print("Recommended: ", tier)
[/codeblock]
